begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local timezone='UTC';
select no_plan();
select ok((select count(*)=2 and bool_and(prosecdef and 'search_path=""'=any(proconfig)) from pg_proc
 where pronamespace='public'::regnamespace and proname in('point_ui_snapshot','point_ui_check_attendance')),'both attendance RPCs pin security-definer search paths');
select ok((select bool_and(has_function_privilege('authenticated',oid,'EXECUTE') and not has_function_privilege('anon',oid,'EXECUTE')
 and not has_function_privilege('service_role',oid,'EXECUTE')) from pg_proc where pronamespace='public'::regnamespace and proname like 'point_ui_%'),'only authenticated actors can invoke UI RPCs');
select ok((select bool_and(not has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) from unnest(array['anon','authenticated','service_role'])r
 cross join unnest(array['private.point_ledger','private.point_attendance_operations'])t),'private ledger and receipts have no raw API grant');
select ok((select relrowsecurity from pg_class where oid='private.point_attendance_operations'::regclass),'receipts retain RLS defense in depth');
select ok(not has_function_privilege('authenticated','private.point_attendance_operation_immutable()','EXECUTE'),'private receipt trigger is not callable');
select is((select count(*) from private.point_policy),0::bigint,'migration does not activate reward policy');
select is((select count(*) from private.point_attendance_operations),0::bigint,'migration manufactures no receipts');
select is((select count(*) from private.point_ledger),0::bigint,'migration manufactures no awards');
select is(private.point_kst_date('2026-10-26 14:59:59.999999+00'),'2026-10-26'::date,'last microsecond before KST midnight remains prior day');
select is(private.point_kst_date('2026-10-26 15:00:00+00'),'2026-10-27'::date,'KST midnight starts the next day');
select is(private.point_kst_date('2028-02-28 15:00:00+00'),'2028-02-29'::date,'KST leap-day boundary is exact');
set local timezone='Pacific/Honolulu';
select is(private.point_kst_date('2026-10-26 15:00:00+00'),'2026-10-27'::date,'session timezone cannot change attendance day');
set local timezone='UTC';
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('d3700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.id(n),'attendance-unit-'||n||'@example.invalid','{}'::jsonb from generate_series(1,9)n;
update public.profiles set call_name='가상출석팬',onboarding_completed_at=clock_timestamp() where id::text like 'd3700000-%';
update public.profiles set role='admin' where id=pg_temp.id(3);
update public.profiles set role='artist' where id=pg_temp.id(4);
update public.profiles set is_restricted=true where id=pg_temp.id(5);
update public.profiles set is_restricted=true,restricted_until=clock_timestamp()-interval '1 second' where id=pg_temp.id(6);
update public.profiles set onboarding_completed_at=null where id=pg_temp.id(7);
create temporary table attendance_context(key text primary key,data jsonb);
grant all on attendance_context to authenticated;
set local role anon;
select throws_ok($$select public.point_ui_snapshot()$$,'42501',null,'anonymous history denied');
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(100))$$,'42501',null,'anonymous award denied');
reset role;
set local role service_role;
select throws_ok($$select public.point_ui_snapshot()$$,'42501',null,'service key cannot impersonate private history');
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(100))$$,'42501',null,'service key cannot invoke browser award');
reset role;
set local role authenticated;
select throws_ok($$select public.point_ui_snapshot()$$,'42501','COMMUNITY_FORBIDDEN','missing actor denied');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
insert into attendance_context values('empty',public.point_ui_snapshot());
select is((select data->>'actor_id' from attendance_context where key='empty'),pg_temp.id(1)::text,'snapshot is bound to current actor');
select is((select data->>'balance' from attendance_context where key='empty'),'0','empty ledger balance is zero');
select is((select data->'entries' from attendance_context where key='empty'),'[]'::jsonb,'empty history is honest');
select is((select data->'next_cursor' from attendance_context where key='empty'),'null'::jsonb,'empty history has no next page');
select is((select data->'attendance_entry_id' from attendance_context where key='empty'),'null'::jsonb,'no fabricated daily receipt');
select is((select data->'attendance_amount' from attendance_context where key='empty'),'null'::jsonb,'missing policy has no invented amount');
select throws_ok($$select public.point_ui_check_attendance(null)$$,'22023','POINT_OPERATION_REQUIRED','operation identity required');
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(100))$$,'55000','POINT_POLICY_UNCONFIGURED','new attendance fails closed without approved policy');
select throws_ok($$select public.point_ui_snapshot(0)$$,'22023','POINT_PAGE_INVALID','zero page rejected');
select throws_ok($$select public.point_ui_snapshot(null)$$,'22023','POINT_PAGE_INVALID','null page rejected');
select throws_ok($$select public.point_ui_snapshot(101)$$,'22023','POINT_PAGE_INVALID','unbounded page rejected');
select throws_ok($$select public.point_ui_snapshot(1,now(),null)$$,'22023','POINT_PAGE_INVALID','timestamp-only cursor rejected');
select throws_ok($$select public.point_ui_snapshot(1,null,pg_temp.id(100))$$,'22023','POINT_PAGE_INVALID','id-only cursor rejected');
select throws_ok($$select public.point_ui_snapshot(1,'infinity',pg_temp.id(100))$$,'22023','POINT_PAGE_INVALID','infinite cursor rejected');
select throws_ok($$select public.point_ui_snapshot(1,'-infinity',pg_temp.id(100))$$,'22023','POINT_PAGE_INVALID','negative infinite cursor rejected');
reset role;
select is((select count(*) from private.point_attendance_operations),0::bigint,'rejected request records no success receipt');
insert into private.point_policy(version,attendance_amount,post_amount,comment_amount,post_daily_cap,comment_daily_cap,deleted_content_treatment)
values('fictional-attendance-tests',10,20,5,0,0,'retain');
set local role authenticated;
select is(public.point_ui_snapshot()->>'attendance_amount','10','snapshot projects exact configured attendance amount');
insert into attendance_context values('first',public.point_ui_check_attendance(pg_temp.id(100)));
select is(public.point_ui_check_attendance(pg_temp.id(100)),(select data from attendance_context where key='first'),'exact operation replay returns original receipt');
select is(public.point_ui_check_attendance(pg_temp.id(101))->>'entry_id',(select data->>'entry_id' from attendance_context where key='first'),'different same-day operation reuses one award');
select is(public.point_check_attendance()::text,(select data->>'entry_id' from attendance_context where key='first'),'raw API and UI share the same daily award');
select is(public.point_balance(),10::bigint,'multiple replay paths add no duplicate amount');
select is((select string_agg(k,',' order by k) from jsonb_object_keys(public.point_ui_check_attendance(pg_temp.id(100)))k),'actor_id,amount,earned_on,entry_id,operation_id','receipt exposes no private policy or correction details');
select is(public.point_ui_snapshot()->>'attendance_entry_id',(select data->>'entry_id' from attendance_context where key='first'),'snapshot marks actual current KST attendance');
select is(public.point_ui_snapshot()->>'kst_date',(select data->>'earned_on' from attendance_context where key='first'),'receipt uses same server KST day');
select is((select string_agg(k,',' order by k) from jsonb_object_keys(public.point_ui_snapshot()->'entries'->0)k),'amount,created_at,earned_on,id,reason','history omits user, actor, policy, reference and correction-note fields');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select is(public.point_ui_snapshot()->>'balance','0','another user cannot read the first balance');
select is(public.point_ui_snapshot()->'entries','[]'::jsonb,'another user cannot read the first history');
insert into attendance_context values('other',public.point_ui_check_attendance(pg_temp.id(100)));
select isnt((select data->>'entry_id' from attendance_context where key='other'),(select data->>'entry_id' from attendance_context where key='first'),'same operation UUID is scoped to actor');
reset role;
select is((select count(*) from private.point_ledger),2::bigint,'two users each have exactly one award');
select is((select count(*) from private.point_attendance_operations),3::bigint,'only successful actor-operation identities are retained');
select throws_ok($$update private.point_attendance_operations set operation_id=pg_temp.id(999)$$,'55000','POINT_OPERATION_IMMUTABLE','receipt identities cannot change');
select throws_ok($$delete from private.point_attendance_operations$$,'55000','POINT_OPERATION_IMMUTABLE','receipts cannot be deleted');
select throws_ok($$truncate private.point_attendance_operations$$,'55000','POINT_OPERATION_IMMUTABLE','receipts cannot be truncated');
select throws_ok($$update private.point_ledger set amount=999$$,'55000','POINT_LEDGER_IMMUTABLE','legacy award immutability retained');
update private.point_policy set version='fictional-changed',attendance_amount=99;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select is(public.point_ui_check_attendance(pg_temp.id(100)),(select data from attendance_context where key='first'),'policy change cannot rewrite exact receipt');
select is(public.point_ui_check_attendance(pg_temp.id(102))->>'amount','10','policy change cannot double-award checked day');
select is(public.point_ui_snapshot()->>'attendance_amount','99','current policy amount is separate from historical award');
reset role;
delete from private.point_policy;
set local role authenticated;
select is(public.point_ui_check_attendance(pg_temp.id(100)),(select data from attendance_context where key='first'),'missing current policy cannot erase existing receipt recovery');
select is(public.point_ui_check_attendance(pg_temp.id(103))->>'amount','10','already-checked day remains idempotent without current policy');
select is(public.point_ui_snapshot()->'attendance_amount','null'::jsonb,'checked day still exposes no amount when policy is absent');
select is(public.point_ui_snapshot()->>'balance','10','policy removal does not remove private historical balance');
select set_config('request.jwt.claim.sub',pg_temp.id(5)::text,true);
select throws_ok($$select public.point_ui_snapshot()$$,'42501','COMMUNITY_FORBIDDEN','restricted user cannot read history');
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(100))$$,'42501','COMMUNITY_FORBIDDEN','restricted user cannot award');
select set_config('request.jwt.claim.sub',pg_temp.id(7)::text,true);
select throws_ok($$select public.point_ui_snapshot()$$,'42501','COMMUNITY_FORBIDDEN','incomplete fan onboarding cannot read');
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(100))$$,'42501','COMMUNITY_FORBIDDEN','incomplete fan onboarding cannot award');
select set_config('request.jwt.claim.sub',pg_temp.id(6)::text,true);
select lives_ok($$select public.point_ui_snapshot()$$,'expired restriction allows private read');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select is(public.point_ui_snapshot()->'entries','[]'::jsonb,'admin reads only own history, not all users');
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select is(public.point_ui_snapshot()->'entries','[]'::jsonb,'artist reads only own history');
reset role;
-- Seed immutable past attendance and same-timestamp entries as fictional legacy
-- state, not a clock override or a public backfill capability.
insert into private.point_ledger(id,user_id,amount,reason,ref_id,earned_on,policy_version,policy_snapshot,actor_id,created_at)
select pg_temp.id(200+n),pg_temp.id(8),n,'attendance',to_char('2001-01-01'::date+n,'YYYY-MM-DD'),'2001-01-01'::date+n,'fictional-past','{}',pg_temp.id(8),'2001-01-10 00:00:00+00' from generate_series(1,4)n;
insert into private.point_attendance_operations(actor_id,operation_id,entry_id) values(pg_temp.id(8),pg_temp.id(200),pg_temp.id(201));
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(8)::text,true);
insert into attendance_context values('past',public.point_ui_check_attendance(pg_temp.id(200)));
select is((select data->>'earned_on' from attendance_context where key='past'),'2001-01-02','retry after a different day returns original attendance day');
select is(public.point_ui_snapshot()->'attendance_entry_id','null'::jsonb,'past receipt never marks current day as checked');
select is(public.point_ui_snapshot()->>'balance','10','past retry cannot award a new day');
insert into attendance_context values('page1',public.point_ui_snapshot(2));
select is(jsonb_array_length((select data->'entries' from attendance_context where key='page1')),2,'bounded history returns exact page size');
select is((select data->'entries'->0->>'id' from attendance_context where key='page1'),pg_temp.id(204)::text,'equal timestamps sort by descending UUID');
select is((select data->'next_cursor'->>'id' from attendance_context where key='page1'),pg_temp.id(203)::text,'cursor is last shown row rather than sentinel');
insert into attendance_context select 'page2',public.point_ui_snapshot(2,(data->'next_cursor'->>'created_at')::timestamptz,(data->'next_cursor'->>'id')::uuid) from attendance_context where key='page1';
select is((select data->'entries'->0->>'id' from attendance_context where key='page2'),pg_temp.id(202)::text,'second page crosses tied timestamp without duplicate');
select is((select data->'entries'->1->>'id' from attendance_context where key='page2'),pg_temp.id(201)::text,'second page retains last entry');
select is((select data->'next_cursor' from attendance_context where key='page2'),'null'::jsonb,'terminal full page does not advertise a phantom next page');
select is((select data->>'balance' from attendance_context where key='page2'),'10','paginated snapshot shows entire balance, not just page sum');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select lives_ok($$select public.point_admin_adjust(pg_temp.id(8),pg_temp.id(300),-3,'Fictional private correction note')$$,'legacy authorized negative correction remains append-only');
select set_config('request.jwt.claim.sub',pg_temp.id(8)::text,true);
select is(public.point_ui_snapshot()->>'balance','7','private summary includes immutable negative corrections');
select is(public.point_ui_snapshot()->'entries'->0->>'reason','admin_adjust','history labels correction rather than false attendance');
select ok(not public.point_ui_snapshot()::text ~ 'Fictional private correction note|admin-correction|ref_id|actor_id.*actor_id','history excludes private correction note and policy reference');
reset role;
insert into private.point_policy(version,attendance_amount,post_amount,comment_amount,post_daily_cap,comment_daily_cap,deleted_content_treatment)
values('fictional-zero',0,0,0,0,0,'retain');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(9)::text,true);
select is(public.point_ui_check_attendance(pg_temp.id(100))->>'amount','0','approved zero amount still produces one attendance receipt');
select is(public.point_ui_snapshot()->>'balance','0','zero attendance does not fabricate positive rewards');
select ok(public.point_ui_snapshot()->'attendance_entry_id'<>'null'::jsonb,'zero reward still marks daily attendance');
reset role;
update private.point_policy set attendance_amount=9007199254740991;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(8)::text,true);
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(999))$$,'22003','POINT_BALANCE_OUT_OF_RANGE','overflow cannot record an award or successful operation');
reset role;
select is((select count(*) from private.point_attendance_operations where actor_id=pg_temp.id(8) and operation_id=pg_temp.id(999)),0::bigint,'failed overflow records no success receipt');
update public.profiles set is_restricted=true where id=pg_temp.id(1);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select throws_ok($$select public.point_ui_check_attendance(pg_temp.id(100))$$,'42501','COMMUNITY_FORBIDDEN','exact replay rechecks current restriction before receipt exposure');
reset role;
select * from finish();
rollback;
